import safepyrun.core as _spc

async def _rishi_run_python(code, g=None, ok_dests=None):
    _spc._rp_globals.set(g)
    inject = {'__builtins__': _spc._builtins, '__name__': '<python>'}
    protect = list(inject) + list(_spc._noexport)
    saved = {k: g[k] for k in protect if k in g}; had = set(saved)
    g.update(inject)
    async def run(src, is_exec=True):
        comp = compile(src, _spc.srcfn(src), 'exec' if is_exec else 'eval', flags=ast.PyCF_ALLOW_TOP_LEVEL_AWAIT)
        r = eval(comp, g)
        return (await r) if inspect.isawaitable(r) else r
    try:
        tree = ast.parse(code)
        warnings.filterwarnings('ignore', category=SyntaxWarning)
        res = None
        if tree.body and isinstance(tree.body[-1], ast.Expr):
            last = tree.body.pop()
            if tree.body: await run(ast.unparse(ast.Module(tree.body, [])))
            res = await run(ast.unparse(ast.Expression(last.value)), False)
        else: await run(code)
        return res
    finally:
        for k in protect:
            if k in had: g[k] = saved[k]
            else: g.pop(k, None)

setattr(_spc, '__run_python', _rishi_run_python)

